116	// ── Elementwise activations + derivatives (the real F.silu / F.softplus). ─────
117	__device__ __forceinline__ float mb_sigmoid(float x) {
118	    return 1.0f / (1.0f + __expf(-x));
119	}
120	__device__ __forceinline__ float mb_sigmoid_grad(float x) {  // s*(1-s)
121	    const float s = mb_sigmoid(x);
122	    return s * (1.0f - s);
123	}
124	__device__ __forceinline__ float mb_silu(float x) {
125	    return x * mb_sigmoid(x);
126	}
127	__device__ __forceinline__ float mb_silu_grad(float x) {
128	    const float s = mb_sigmoid(x);
129	    return s * (1.0f + x * (1.0f - s));
130	}
131	__device__ __forceinline__ float mb_softplus(float x) {
132	    // log1p(exp(x)), guarded for large x (matches torch threshold=20).
133	    return (x > 20.0f) ? x : log1pf(__expf(x));
134	}
135	__device__ __forceinline__ float mb_softplus_grad(float x) {  // sigmoid(x)
136	    return mb_sigmoid(x);
137	}
