139	// ── Per-CTA scratch for one sample. POD held in smem (one instance per CTA).
140	//    BOTH layers' forward activations are cached. The scan complex STATE is NOT
141	//    here (per-thread registers — the seq=8 exploit). ──────────────────────────
142	struct MambaSampleSmem {
143	    // Cross-block residual stream: the INPUT to each block (= residual x), and
144	    // the final-block output feeding the head norm.
145	    float layer_in[mb::kLayers][mb::kSeq][mb::kD];   // block input (residual)
146	    float final_in[mb::kSeq][mb::kD];                // final-block output -> head
147	    // Per-block cached forward activations (both blocks): the values the backward
148	    // reads. The block-level "h1" (= x + mixer_out) is cached so mlp_norm's input
149	    // and the mixer-residual reconstruction are available in the backward.
150	    struct LayerAct {
151	        // --- mixer pre-norm (RMSNorm_mix) cache: only the recip (xhat recomputed
152	        //     in bwd from the raw block input layer_in[li], saving kSeq*kD floats) ---
153	        float mixn_r[mb::kSeq];                // rsqrt(mean(x^2)+eps)
154	        // --- mixer internals ---
155	        float x_in[mb::kSeq][mb::kDInner];     // in_proj first half (= x_main, scan/x_proj/D input)
156	        float z[mb::kSeq][mb::kDInner];        // in_proj second half (gate)
157	        float dt_lr[mb::kSeq][mb::kDtRank];    // dt_proj input (x_proj slice)
158	        float dt_pre[mb::kSeq][mb::kNHeads];   // dt_proj out + bias (PRE-softplus, per head)
159	        float A_mod[mb::kSeq][mb::kNHeads];    // x_proj A_mod slice (per head)
160	        float u_lam[mb::kSeq][mb::kNHeads];    // x_proj lambda logit (per head)
161	        float theta[mb::kSeq][mb::kStateC];    // x_proj theta slice (head-shared)
162	        // BCNorm caches: pre-norm raw streams + their rms recip. Streams: Br,Bi,Cr,Ci.
163	        float Br[mb::kSeq][mb::kStateC];       // pre-BCNorm B real
164	        float Bi[mb::kSeq][mb::kStateC];       // pre-BCNorm B imag (Bhat)
165	        float Cr[mb::kSeq][mb::kStateC];       // pre-BCNorm C real
166	        float Ci[mb::kSeq][mb::kStateC];       // pre-BCNorm C imag (Chat)
167	        float Br_r[mb::kSeq]; float Bi_r[mb::kSeq];   // BCNorm rms recips
168	        float Cr_r[mb::kSeq]; float Ci_r[mb::kSeq];
169	        // post-norm+bias 2-vector streams (the scan reads these):
170	        float Bbar[mb::kSeq][mb::kStateC][2];  // (Br2, Bi2)
171	        float Cbar[mb::kSeq][mb::kStateC][2];  // (Cr2, -Ci2)
172	        float y_scan[mb::kSeq][mb::kDInner];   // selective-scan output (per channel)
173	        // --- block inter-residual + mlp pre-norm (RMSNorm_mlp) cache ---
174	        float h1[mb::kSeq][mb::kD];            // x + mixer_out (mlp_norm input; raw x for mlpn bwd)
175	        float mlpn_r[mb::kSeq];                // mlp_norm rms recip (xhat recomputed from h1 in bwd)
176	        // --- SwiGLU internals ---
177	        float g_pre[mb::kSeq][mb::kDff];       // gate_proj out (pre-SiLU)
178	        float u_mlp[mb::kSeq][mb::kDff];       // up_proj out
179	    } act[mb::kLayers];
180	    // Final-norm caches (last position used) + head logits.
181	    float fn_xhat[mb::kSeq][mb::kD];
182	    float fn_r[mb::kSeq];
183	    float logits[mb::kPHead];
184	    // Backward adjoint scratch (reused across the per-block chain).
185	    float dh[mb::kSeq][mb::kD];                // running grad wrt block output
186	    float dr[mb::kSeq][mb::kD];                // RMSNorm-bwd output / residual scratch
187	    float adj_a[mb::kSeq][mb::kDInner];        // d_inner-wide scratch
188	    float adj_b[mb::kSeq][mb::kDInner];        // d_inner-wide scratch
189	    float adj_c[mb::kSeq][mb::kDInner];        // d_inner-wide scratch
190	    float wff_a[mb::kSeq][mb::kDff];           // d_ff-wide scratch (MLP)
191	    float wff_b[mb::kSeq][mb::kDff];           // d_ff-wide scratch (MLP)
192	    float xproj[mb::kSeq][mb::kXProj];         // x_proj fwd out / dx_proj staging
193	    // scan-bwd cross-channel reduce targets (head-shared), per timestep:
194	    float dBbar[mb::kSeq][mb::kStateC][2];
195	    float dCbar[mb::kSeq][mb::kStateC][2];
196	    float dtheta[mb::kSeq][mb::kStateC];
197	    // Reductions across threads. 256 threads = 8 warps; the two-level block
198	    // reduce uses red[warp] (warp<=7) then red[0]. 64 slots = ample headroom
199	    // (kept small so the CTA dynamic smem stays under the H100 per-block opt-in
200	    // cap of 227 KB — the full 256-slot red pushed sizeof past it by ~0.5 KB).
201	    float red[64];
202	};
