904	// ════════════════════════════════════════════════════════════════════════
905	//  FORWARD for one sample (CTA-cooperative). Mirrors mamba3_oracle.model_forward
906	//  + block_forward. Caches BOTH blocks' activations into sm->act[li]. Returns NLL.
907	// ════════════════════════════════════════════════════════════════════════
908	__device__ inline float mb_forward_sample(const MambaWeights& w, const int* tokens_s,
909	                                    int target, MambaSampleSmem* sm) {
910	    // Embedding + positional -> layer_in[0].
911	    for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
912	        const int s = idx / mb::kD, j = idx % mb::kD;
913	        sm->layer_in[0][s][j] = w.tok[(int64_t)tokens_s[s] * mb::kD + j]
914	                              + w.pos[(int64_t)s * mb::kD + j];
915	    }
916	    __syncthreads();
917	
918	    for (int li = 0; li < mb::kLayers; ++li) {
919	        const MambaWeights::Layer& L = w.layer[li];
920	        MambaSampleSmem::LayerAct* a = &sm->act[li];
921	        float* hin = &sm->layer_in[li][0][0];   // block input (residual)
922	        // --- mixer sub-block: h1 = hin + mixer(RMSNorm_mix(hin)) ---
923	        // xhat written to throwaway scratch (adj_c) — only the recip is cached; the
924	        // backward recomputes xhat from the raw block input layer_in[li].
925	        mb_rmsnorm_fwd(hin, L.mixn_w, &sm->dr[0][0], &sm->adj_c[0][0], &a->mixn_r[0],
926	                       sm->red, mb::kD, mb::kD);   // xn -> sm->dr
927	        // mix_out written into adj_b at WIDTH-kD stride (s*kD+j); read it the same way.
928	        float* mo = &sm->adj_b[0][0];
929	        mb_mixer_fwd(L, &sm->dr[0][0], a, mo, sm);   // mix_out -> sm->adj_b (kD-strided)
930	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
931	            const int s = idx / mb::kD, j = idx % mb::kD;
932	            a->h1[s][j] = hin[s * mb::kD + j] + mo[s * mb::kD + j];   // h1 = x + mixer_out
933	        }
934	        __syncthreads();
935	        // --- SwiGLU sub-block: h2 = h1 + mlp(RMSNorm_mlp(h1)) ---
936	        // xhat throwaway (adj_c); backward recomputes from the raw h1.
937	        mb_rmsnorm_fwd(&a->h1[0][0], L.mlpn_w, &sm->dr[0][0], &sm->adj_c[0][0], &a->mlpn_r[0],
938	                       sm->red, mb::kD, mb::kD);   // h1n -> sm->dr
939	        mb_swiglu_fwd(L, &sm->dr[0][0], a, mo, sm);  // mlp_out -> sm->adj_b (kD-strided)
940	        float* dst = (li + 1 < mb::kLayers) ? &sm->layer_in[li + 1][0][0] : &sm->final_in[0][0];
941	        for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
942	            const int s = idx / mb::kD, j = idx % mb::kD;
943	            dst[s * mb::kD + j] = a->h1[s][j] + mo[s * mb::kD + j];   // h2 = h1 + mlp_out
944	        }
945	        __syncthreads();
946	    }
947	
948	    // Final RMSNorm (LAST position) + head -> logits -> NLL.
949	    const float* hlast = &sm->final_in[mb::kSeq - 1][0];
950	    float ss = 0.0f;
951	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) { float v = hlast[j]; ss += v * v; }
952	    float ms = mb_block_sum(ss, sm->red) / (float)mb::kD;
953	    float r = rsqrtf(ms + mb::kRmsEps);
954	    if (threadIdx.x == 0) sm->fn_r[mb::kSeq - 1] = r;
955	    for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
956	        float xh = hlast[j] * r;
957	        sm->fn_xhat[mb::kSeq - 1][j] = xh;
958	        sm->adj_a[0][j] = xh * w.norm_w[j];   // hn (RMSNorm, NO bias) -> adj_a[0]
959	    }
960	    __syncthreads();
961	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
962	        const float* Wr = w.out_w + (int64_t)o * mb::kD;
963	        float acc = w.out_b[o];
964	        #pragma unroll 4
965	        for (int k = 0; k < mb::kD; ++k) acc += sm->adj_a[0][k] * Wr[k];
966	        sm->logits[o] = acc;
967	    }
968	    __syncthreads();
969	    float lmax = -CUDART_INF_F;
970	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) lmax = fmaxf(lmax, sm->logits[o]);
971	    lmax = mb_block_max(lmax, sm->red);
972	    float es = 0.0f;
973	    for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) es += __expf(sm->logits[o] - lmax);
974	    es = mb_block_sum(es, sm->red);
975	    float logz = lmax + __logf(es);
976	    return logz - sm->logits[target];
977	}
