529	template <OptId Opt, class Par = ::sg::fused::par::SingleGPU>
530	__global__ void SG_MBTC_LAUNCH_BOUNDS
531	fused_mamba_megakernel_tc(PersistentContext ctx,
532	                          float* __restrict__ params,
533	                          MambaTokenCtx tok,
534	                          float* __restrict__ grad,
535	                          float lr, int step, FusedOptState st,
536	                          ::sg::fused::par::CommCtx comm = {}) {
537	    // MAMBA-3 design: the "TC" megakernel runs the VALIDATED scalar per-sample
538	    // fwd+bwd (model_stage_mamba3.cuh, mb_forward_sample/mb_backward_sample —
539	    // matched to the fp64 oracle to ~2e-6) batch-parallel into a per-CTA FULL-grad
540	    // partial, then a deterministic ascending-CTA reduce + the canonical optimizer
541	    // tail (incl. the SAM 2nd backward for looksam/SG/SG2). The Mamba-3 mixer is
542	    // scan-dominated (the projections are a tiny share of the wall), so the scalar
543	    // engine IS the production path; the wgmma-projection dW machinery is bypassed.
544	    // The per-sample MambaSampleSmem (~227 KB) lives in DYNAMIC smem (opt-in by the
545	    // launcher), exactly like the scalar Mamba megakernel.
546	    extern __shared__ char mamba_tc_smem_raw[];
547	    MambaSampleSmem& sm = *reinterpret_cast<MambaSampleSmem*>(mamba_tc_smem_raw);
548	    GridBarrier bar = ctx.barrier();
549	    // TP transport: constructed ONLY inside the kTPComm P1 branch (EDIT M-C below)
550	    // via make_transport_from_comm<Par>(comm), so NOTHING TP-related is named on the
551	    // SingleGPU path — the cleanest PTX identity (decoder tp_kernel.md §5 RECOMMENDED).
552	    (void)comm;  // default-constructed POD, unread on SingleGPU (kTPComm==false)
553	    constexpr bool kSamCoupled = (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
554	                                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2);
555	    (void)kSamCoupled;
556	    const int cta = blockIdx.x;
557	    const int nCTA = (int)ctx.n_ctas;
558	    const int B = tok.B;
559	    const int T = B * mb::kSeq;
560	    (void)T;
561	
562	    // Workspace partition. The per-CTA partial is the FULL grad [total] (scalar
563	    // design), NOT the dW-output-stationary split + non-GEMM partial. acts/scratch/
564	    // dw_part are unused on this path (kept zero-width in mb_tc_workspace_floats).
565	    float* ws = tok.workspace;
566	    const int64_t total_p = kMambaTotalElems;
567	    float* part_base = ws;                                  // [nCTA * total]
568	    float* loss_part = part_base + (int64_t)nCTA * total_p; // [nCTA]
569	    float* loss_out  = loss_part + nCTA;                    // [1]
570	    float* dw_part   = loss_out + 1;                        // unused (kept for layout parity)
571	    (void)dw_part;
572	    // STAGED-opt (Prodigy P2.6) cross-CTA reduce slots: [r slots | s slots | reduced d]
573	    // = 2*nCTA+1. Carved after the loss slot (dw_part is zero-width here).
574	    float* opt_reduce = loss_out + 1;
575	    // LookSAM SAM 2nd-backward scratch, carved AFTER the Prodigy reduce slots (mamba has
576	    // NO Muon region — unlike the decoder/vit twins — so this follows opt_reduce; term
577	    // order matches mb_tc_workspace_floats). Carving it here keeps every prior region's
578	    // offset unchanged, so the already-green cells are byte-identical. Layout:
579	    //   [sam_backup (total)] [sam_grad (total)]. Unused unless Opt==LookSAM.
580	    float* sam_backup = opt_reduce + mb_tc_opt_reduce_floats(nCTA);
581	    float* sam_grad   = sam_backup + kMambaTotalElems;
582	    // Muon NS per-matrix scratch, carved AFTER the LookSAM sam scratch (term order matches
583	    // mb_tc_workspace_floats — carving it LAST [before the optional profiler] keeps every
584	    // prior region's offset unchanged, so the already-green mamba cells are byte-identical).
585	    // Unused unless Opt==Muon. Layout (mirrors the decoder/vit twins):
586	    //   [muon_X | muon_AX | muon_AAX | muon_orth] (each kMbMuonMaxNumel)
587	    //   [muon_A (kMbMuonMaxRows²)] [nrm_partials (nCTA)] [inv_norm (1)]
588	    float* muon_base  = sam_grad + kMambaTotalElems;
589	    // SuperGrok2 meta-net per-CTA scratch, carved AFTER the Muon NS scratch (term order
590	    // matches mb_tc_workspace_floats — carving it LAST [before the optional profiler]
591	    // keeps every prior region's offset unchanged, so the already-green mamba cells are
592	    // byte-identical). Each CTA owns mb_sg2_ws_stride_floats() (row_off64 staging +
593	    // meta-net scratch). ALIGN to 8 bytes (even float offset): the per-CTA slice fronts
594	    // an int64 row_off64 staging array; kMambaTotalElems is odd so sam_grad+total lands
595	    // on an odd float offset (4-byte) → an int64 read there is misaligned. Round up to
596	    // the next even float (the carve reserves +1 slack). Unused unless Opt==SuperGrok2.
597	    float* sg2_ws_base = muon_base + mb_tc_muon_floats(nCTA);
598	    if (((uintptr_t)sg2_ws_base & 0x7) != 0) sg2_ws_base += 1;   // → 8-byte aligned
599	    (void)sg2_ws_base;   // referenced only by the SuperGrok2 P3-SG2 phase
600	#if SG_MB_TC_PROFILE
601	    // 8-byte align the double accumulator: round the float offset up to an even
602	    // count so reinterpret_cast<double*> is aligned (past the SG2 scratch — the
603	    // phase-profiler is the LAST workspace term, mirroring mb_tc_workspace_floats).
604	    float* prof_f = sg2_ws_base + mb_tc_sg2_floats(nCTA);
605	    uintptr_t _pa = reinterpret_cast<uintptr_t>(prof_f);
606	    if (_pa & 0x7u) prof_f = reinterpret_cast<float*>((_pa + 7u) & ~uintptr_t(7u));
607	    double* prof = reinterpret_cast<double*>(prof_f);   // [nCTA*SLOTS], host-zeroed
608	    long long _pt = 0;
609	#endif
610	
611	    float* my_part = part_base + (int64_t)cta * total_p;   // this CTA's FULL grad partial
612	    MambaWeights w = mb_bind(params);
613	    MambaGrad g = mb_bind_grad(my_part);
614	
615	    // ── P0: zero this CTA's FULL grad partial + loss slot. ──
616	    for (int64_t i = threadIdx.x; i < total_p; i += blockDim.x) my_part[i] = 0.0f;
617	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
618	    bar.sync();   // B0
619	
620	    // ── P1: fwd+bwd (scalar per-sample). Fixed contiguous slice [b0,b1) for this
621	    //    CTA; the whole CTA cooperates on ONE sample at a time. ──
622	    if constexpr (!Par::kTPComm) {
623	        // ░░ DEFAULT / SingleGPU path — BYTE-IDENTICAL to the pre-Par kernel
624	        //    (batch-parallel: each CTA owns a contiguous batch slice). ░░
625	        const int base = B / nCTA, rem = B % nCTA;
626	        const int b0 = cta * base + (cta < rem ? cta : rem);
627	        const int cnt = base + (cta < rem ? 1 : 0);
628	        const int b1 = b0 + cnt;
629	        __shared__ int tok_s[mb::kSeq];
630	        __shared__ int tgt_s;
631	        float nll_acc = 0.0f;
632	        SG_MBTC_PROF_TIC(_pt);
633	        for (int b = b0; b < b1; ++b) {
634	            if (threadIdx.x < mb::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * mb::kSeq + threadIdx.x];

634	            if (threadIdx.x < mb::kSeq) tok_s[threadIdx.x] = tok.tokens[(int64_t)b * mb::kSeq + threadIdx.x];
635	            if (threadIdx.x == 0) tgt_s = tok.targets[b];
636	            __syncthreads();
637	            float nll = mb_forward_sample(w, tok_s, tgt_s, &sm);
638	            mb_backward_sample(w, g, tok_s, tgt_s, B, &sm);
639	            if (threadIdx.x == 0) nll_acc += nll;
640	            __syncthreads();
641	        }
642	        if (threadIdx.x == 0) loss_part[cta] = nll_acc;
643	        SG_MBTC_PROF_ACC(0, _pt);
644	    } else {
645	        // ░░ kTPComm path — GRID-LOCKSTEP OVER SAMPLES so tr.rendezvous(bar) at the 4
646	        //    reduce points (mb_*_sample_tp out_proj/down fwd + in_proj/gate-up dX bwd)
647	        //    is reached the SAME number of times by every CTA on this GPU (the decoder
648	        //    tp_kernel.md §1 deadlock fix, applied to the scalar batch-parallel P1).
649	        //
650	        //    The decoder shards a TILE across the P CTA-groups; Mamba's unit of work is
651	        //    a SAMPLE (one CTA cooperatively per sample), so the analogue is: all P
652	        //    CTA-groups cooperate on the SAME sample each round, each owning the rank's
653	        //    weight-shard of the row-parallel out_proj/down. ROUND COUNT is GRID-UNIFORM
654	        //    because the activations (the batch) are REPLICATED across TP ranks (TP
655	        //    shards WEIGHTS, not the batch — decoder §1): every PE/GPU sees the SAME B
656	        //    ⇒ SAME n_rounds. A virtual PE with no sample in a round STILL calls
657	        //    tr.rendezvous(bar) (active=false, math skipped) so the arrival count is
658	        //    grid-uniform — the §1 lockstep invariant.
659	        const int P            = Par::kTP;                   // TP degree (constexpr; == tr.n_pes())
660	        const int ctas_per_pe  = nCTA / P;                   // launcher asserts nCTA % P == 0
661	        const int cta_in_pe    = ::sg::fused::sm90::tp::LoopbackTransport::cta_within_pe(cta, nCTA, P);
662	        const int64_t slot_pub = (int64_t)cta_in_pe * 2 * mbtc::mb_tp_slot_floats();
663	        const int64_t slot_red = slot_pub + mbtc::mb_tp_slot_floats();

1260	                    apply_optimizer<Opt>(p, gg, (int64_t)i, step, ts);
1261	            }
1262	        }
1263	    }
1264	    SG_MBTC_PROF_ACC(3, _pt);          // close P3
1265	}
