1296	template <OptId Opt, class Par = ::sg::fused::par::SingleGPU>
1297	cudaError_t launch_fused_mamba_megakernel_tc(
1298	        PersistentContext ctx, float* params, MambaTokenCtx tok,
1299	        float* grad, float lr, int step, FusedOptState st, cudaStream_t stream,
1300	        int ncta_cap = 0, const ::sg::fused::par::CommCtx& comm = {}) {
1301	    int dev = 0;
1302	    cudaError_t err = cudaGetDevice(&dev);
1303	    if (err != cudaSuccess) return err;
1304	    int n_sms = 0;
1305	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
1306	    if (err != cudaSuccess) return err;
1307	
1308	    // MAMBA-3: DYNAMIC smem opt-in (the per-sample MambaSampleSmem ~227 KB). Three
1309	    // mandatory steps (cudaFuncSetAttribute + dyn_smem in the occ query + dyn_smem
1310	    // at <<<>>>); one block/SM by design (occ=1, smem-bound).
1311	    const int dyn_smem = (int)kMambaSmemBytes;
1312	    err = cudaFuncSetAttribute((const void*)&fused_mamba_megakernel_tc<Opt, Par>,
1313	                               cudaFuncAttributeMaxDynamicSharedMemorySize, dyn_smem);
1314	    if (err != cudaSuccess) return err;
1315	    int occ = 0;
1316	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
1317	        &occ, (const void*)&fused_mamba_megakernel_tc<Opt, Par>, SG_MB_TC_MEGA_BLOCK,
