407	                tr, slot_pub, &sm->adj_b[0][0], (int64_t)mb::kSeq * mb::kD, threadIdx.x, blockDim.x);
408	            tr.rendezvous(bar);
409	            if (active) {
410	                float* mo = &sm->adj_b[0][0];
411	                float* dst = (li + 1 < mb::kLayers) ? &sm->layer_in[li + 1][0][0] : &sm->final_in[0][0];
412	                for (int idx = threadIdx.x; idx < mb::kSeq * mb::kD; idx += blockDim.x) {
413	                    const int s = idx / mb::kD, j = idx % mb::kD;
414	                    dst[s * mb::kD + j] = a->h1[s][j] + mo[s * mb::kD + j];   // h2 = h1 + mlp_out
415	                }
416	                __syncthreads();
417	            }
418	        }
419	        // Final RMSNorm + head + NLL (replicated, only when active).
420	        if (active) {
421	            const float* hlast = &sm->final_in[mb::kSeq - 1][0];
422	            float ss = 0.0f;
423	            for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) { float v = hlast[j]; ss += v * v; }
424	            float ms = mb_block_sum(ss, sm->red) / (float)mb::kD;
425	            float r = rsqrtf(ms + mb::kRmsEps);
426	            if (threadIdx.x == 0) sm->fn_r[mb::kSeq - 1] = r;
427	            for (int j = threadIdx.x; j < mb::kD; j += blockDim.x) {
428	                float xh = hlast[j] * r;
429	                sm->fn_xhat[mb::kSeq - 1][j] = xh;
430	                sm->adj_a[0][j] = xh * w.norm_w[j];
431	            }
432	            __syncthreads();
433	            for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) {
434	                const float* Wr = w.out_w + (int64_t)o * mb::kD;
435	                float acc = w.out_b[o];
436	                #pragma unroll 4
437	                for (int k = 0; k < mb::kD; ++k) acc += sm->adj_a[0][k] * Wr[k];
438	                sm->logits[o] = acc;
439	            }
440	            __syncthreads();
441	            float lmax = -CUDART_INF_F;
442	            for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) lmax = fmaxf(lmax, sm->logits[o]);
443	            lmax = mb_block_max(lmax, sm->red);
444	            float es = 0.0f;
445	            for (int o = threadIdx.x; o < mb::kPHead; o += blockDim.x) es += __expf(sm->logits[o] - lmax);
446	            es = mb_block_sum(es, sm->red);
447	            float logz = lmax + __logf(es);
448	            nll_acc = logz - sm->logits[target];
449	        }
450	        return nll_acc;
451	    }
