    + (int64_t)SG_MB_LAYERS*kMbOneLayerActFloats
    + (SG_MB_SEQ*SG_MB_D + SG_MB_SEQ + SG_MB_PHEAD)
    + 2*SG_MB_SEQ*SG_MB_D
    + 3*SG_MB_SEQ*SG_MB_DINNER + 2*SG_MB_SEQ*SG_MB_DFF
    + SG_MB_SEQ*SG_MB_XPROJ
